class Solution {
public:
    int numberOfWays(int n, int x) {
        const int MOD = 1000000007;
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; ; i++) {
            int p = 1;
            for (int k = 0; k < x; k++) p *= i;
            if (p > n) break;
            for (int j = n; j >= p; j--) {
                dp[j] = (dp[j] + dp[j - p]) % MOD;
            }
        }
        return dp[n];
    }
};
